//! Actual saved S2 with synthetic symmetric errors; real allocation custody observed.
use super::*;
use sha2::{Digest,Sha256};
use std::{cell::RefCell, sync::atomic::{AtomicUsize,Ordering}};
use aspis_statement::pool_v1::PoolV1PairForestTerminalStatementV1;
const PROOF:&[u8]=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/research/100bit-spend-path-20261013/evidence/p3-private-leaf-salts-20261013/p3-pool-13/transfer-1023-os-task/r1-s2-proof.bin"));
const PUBLIC:&[u8]=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/research/100bit-spend-path-20261013/evidence/p3-private-leaf-salts-20261013/p3-pool-13/transfer-1023-os-task/r1-s2-public-asf8.bin"));
static CLOCK:AtomicUsize=AtomicUsize::new(0);static CLAIMS:AtomicUsize=AtomicUsize::new(0);static DROPPED:AtomicUsize=AtomicUsize::new(0);
fn tick()->usize {CLOCK.fetch_add(1,Ordering::SeqCst)+1}
struct WatchAllocator;
#[global_allocator]static ALLOCATOR:WatchAllocator=WatchAllocator;
unsafe impl std::alloc::GlobalAlloc for WatchAllocator {
 unsafe fn alloc(&self,l:std::alloc::Layout)->*mut u8 {std::alloc::GlobalAlloc::alloc(&std::alloc::System,l)}
 unsafe fn dealloc(&self,p:*mut u8,l:std::alloc::Layout){if CLAIMS.compare_exchange(p as usize,0,Ordering::SeqCst,Ordering::SeqCst).is_ok(){DROPPED.store(tick(),Ordering::SeqCst);}std::alloc::GlobalAlloc::dealloc(&std::alloc::System,p,l)}
 unsafe fn realloc(&self,p:*mut u8,l:std::alloc::Layout,n:usize)->*mut u8{std::alloc::GlobalAlloc::realloc(&std::alloc::System,p,l,n)}
}
#[derive(Clone,Copy,Debug,PartialEq,Eq,Default)]enum Fault {#[default]None,Parse,Semantic,Prepare,Geometry,Query(usize),Checkpoint}
#[derive(Clone,Debug,PartialEq,Eq,Default)]struct Log {fault:Fault,events:Vec<(usize,&'static str)>,geometry:Vec<(usize,usize,[u32;22])>,queries:Vec<(usize,Vec<u8>)>,checkpoints:Vec<Vec<u8>>,phases:Vec<Phase>,digests:Vec<(Vec<Vec<u8>>,[u8;32])>}
std::thread_local!{static LOG:RefCell<Log>=RefCell::new(Log::default());}
fn event(s:&'static str){let at=tick();LOG.with(|l|l.borrow_mut().events.push((at,s)));}
fn fault()->Fault {LOG.with(|s|s.borrow().fault)}
pub(crate) fn semantic<H:Digest32>(public:Public<'_>,bytes:&[u8],hash:H,obs:Observer)->Result<crate::r1_semantic::Verified<H>,Error>{
 event("semantic-entry");if fault()==Fault::Semantic{return Err(Error::Semantic)}
 let sem=crate::r1_semantic::verify_observed(public,bytes,hash,obs).map_err(|_|Error::Semantic)?;
 assert_eq!(CLAIMS.swap(sem.claims.as_ptr() as usize,Ordering::SeqCst),0);event("claims-owned");Ok(sem)
}
pub(crate) fn before_prepare()->bool {event("prepare-entry");fault()==Fault::Prepare}
fn kb(v:K)->[u8;16]{let mut b=[0;16];v.write_le_bytes(&mut b);b}
fn state(p:&Prepared,a:&Accumulator)->Vec<u8>{let mut b=alloc::vec![p.variant.tag()];for root in p.roots{b.extend_from_slice(&root)}for v in [p.gamma,p.kappa,p.alpha[0],p.alpha[1]]{b.extend_from_slice(&v.to_le_bytes())}b.extend_from_slice(&kb(p.rho));for q in p.queries{b.extend_from_slice(&q.to_le_bytes())}for x in p.semantic_alpha{b.extend_from_slice(&kb(x))}for z in p.z{b.extend_from_slice(&kb(z.x));b.extend_from_slice(&kb(z.y))}b.extend_from_slice(&p.claim.to_le_bytes());b.extend_from_slice(&p.state);b.extend_from_slice(&(a.next as u64).to_le_bytes());b.extend_from_slice(&a.rhs.to_le_bytes());b.extend_from_slice(&kb(a.power));for x in &a.weights{b.extend_from_slice(&kb(*x))}b}
pub(crate) fn before_geometry(q:&[u32;22],s:usize,e:usize)->bool {event("geometry-entry");LOG.with(|l|l.borrow_mut().geometry.push((s,e,*q)));fault()==Fault::Geometry}
pub(crate) fn before_query(p:&Prepared,a:&Accumulator)->bool {event("query-entry");LOG.with(|l|l.borrow_mut().queries.push((a.next,state(p,a))));fault()==Fault::Query(a.next)}
pub(crate) fn checkpoint_result<H:Digest32>(p:&Prepared,a:&Accumulator,proof:&[u8],public:&[u8],h:H)->Result<Vec<u8>,Error>{event("checkpoint-entry");LOG.with(|l|l.borrow_mut().checkpoints.push(state(p,a)));if fault()==Fault::Checkpoint{Err(Error::Checkpoint)}else{Ok(checkpoint(p,a,proof,public,h))}}
#[derive(Clone,Copy)]struct RecordedSha;
impl Digest32 for RecordedSha {fn digest(&self,parts:&[&[u8]])->[u8;32]{event("digest");let mut h=Sha256::new();for p in parts{h.update(p)}let out=h.finalize().into();LOG.with(|l|l.borrow_mut().digests.push((parts.iter().map(|x|x.to_vec()).collect(),out)));out}}
fn observer(p:Phase){event("observer");LOG.with(|l|l.borrow_mut().phases.push(p))}
#[derive(Debug,PartialEq,Eq)]struct Outcome {result:Result<Vec<u8>,Error>,log:Log,drop_at:usize}
fn run(old:bool,f:Fault,observed:bool)->Outcome{
 assert_eq!(CLAIMS.load(Ordering::SeqCst),0);CLOCK.store(0,Ordering::SeqCst);DROPPED.store(0,Ordering::SeqCst);LOG.with(|l|*l.borrow_mut()=Log{fault:f,..Log::default()});
 let statement=aspis_statement::pool_v1::decode_pool_v1_pair_forest_terminal_statement_v1(PUBLIC).unwrap();let public=statement_public(&statement);let proof=if f==Fault::Parse{&PROOF[..8]}else{PROOF};let obs=if observed{Some(observer as fn(Phase))}else{None};
 let result=if old{migration_old_tx1(public,PUBLIC,proof,22,RecordedSha,obs)}else{tx1(public,PUBLIC,proof,22,RecordedSha,obs)};
 assert_eq!(CLAIMS.load(Ordering::SeqCst),0,"claims must drop on actual return");Outcome{result,log:LOG.with(|l|l.borrow().clone()),drop_at:DROPPED.load(Ordering::SeqCst)}
}
#[test]fn decision1h_saved_s2_exact_old_new_faults_and_claims(){
 assert!(!cfg!(feature="prover"));
 for observed in [false,true]{let success=run(true,Fault::None,observed);assert!(success.result.is_ok());
 for f in [Fault::None,Fault::Parse,Fault::Semantic,Fault::Prepare,Fault::Geometry,Fault::Query(0),Fault::Query(21),Fault::Checkpoint]{let a=run(true,f,observed);let b=run(false,f,observed);assert_eq!(a,b,"fault={f:?} observed={observed}");assert_eq!(a.result.as_ref().err().copied(),match f{Fault::None=>None,Fault::Parse=>Some(Error::Parse),Fault::Semantic=>Some(Error::Semantic),Fault::Prepare=>Some(Error::Transcript),Fault::Checkpoint=>Some(Error::Checkpoint),_=>Some(Error::Query)});
 if matches!(f,Fault::Parse|Fault::Semantic){assert_eq!(a.drop_at,0)}else{assert!(a.drop_at>a.log.events.last().unwrap().0,"actual claims drop after every retained caller event")}
 assert_eq!(a.log.digests,&success.log.digests[..a.log.digests.len()]);
 if observed {let phases=&success.log.phases;let cut=match f{Fault::None=>phases.len(),Fault::Parse=>0,Fault::Semantic=>1,Fault::Prepare=>phases.iter().position(|p|*p==Phase::Semantic).unwrap()+1,Fault::Geometry|Fault::Query(0)=>phases.iter().position(|p|*p==Phase::Prepare).unwrap()+1,Fault::Query(21)=>phases.iter().position(|p|*p==Phase::Merkle(21)).unwrap(),Fault::Checkpoint=>phases.len()-1,Fault::Query(_)=>unreachable!()};assert_eq!(a.log.phases,&phases[..cut]);}else{assert!(a.log.phases.is_empty())}
 std::println!("DECISION1H_REAL_CASE observed={observed} fault={f:?} detail={} equal=true {a:?}",cfg!(feature="detail-phases"));
 }}std::println!("DECISION1H_REAL_PASS cases=16 actual_claims_deallocation=true prover=false trace_values=disabled");
}

